      "ballot_id": "B005",
      "proposed_laureates": [
        "Immanuel Bloch",
        "Juan Ignacio Cirac",
        "Markus Greiner",
        "Peter Zoller"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattices made controlled quantum simulation of interacting many-body systems a new experimental field, with lasting value for fundamental physics and materials theory.",
        "attribution": "Bloch and Greiner established key experimental results; Cirac and Zoller supplied foundational proposals and theory. The four contributions are distinct and complementary.",
        "maturity": "The platform and its physical results have been reproduced and extended over many years.",
        "uncertainties": [
          "The breadth of the credited achievement may make a focused prize citation difficult."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B008",
      "proposed_laureates": [
        "Christian Pfleiderer",
        "Roland Wiesendanger",
        "Yoshinori Tokura"
      ],
      "assessment": {
        "nobel_worthiness": "Magnetic skyrmions revealed topologically protected nanoscale magnetic textures and opened a substantial new area of condensed-matter physics.",
        "attribution": "Pfleiderer and Tokura were central to identifying skyrmion phases in materials; Wiesendanger demonstrated and resolved individual skyrmions with scanning probe methods.",
        "maturity": "The textures have been observed in multiple materials and by independent techniques, while their applications remain under development.",
        "uncertainties": [
          "The discovery unfolded across several materials and experimental milestones, complicating a single prize boundary."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B006",
      "proposed_laureates": [
        "Nicola A. Spaldin",
        "Ramamoorthy Ramesh",
        "Yoshinori Tokura"
      ],
      "assessment": {
        "nobel_worthiness": "Magnetoelectric multiferroics established a rich class of materials in which magnetic and electric order are coupled, with deep consequences for materials physics.",
        "attribution": "Spaldin clarified the physical mechanisms and design principles; Ramesh and Tokura were leading experimental discoverers and developers of key materials and effects.",
        "maturity": "The coupling phenomena are well established across many compounds, though practical devices have not matched the early promise.",
        "uncertainties": [
          "The field has many contributors, and the boundary between discovery, explanation, and materials development needs careful definition."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B013",
      "proposed_laureates": [
        "Claudio Castelnovo",
        "Roderich Moessner",
        "Shivaji L. Sondhi"
      ],
      "assessment": {
        "nobel_worthiness": "The prediction and observation of emergent magnetic monopole excitations in spin ice gave a striking demonstration of fractionalized quasiparticles in a solid.",
        "attribution": "Castelnovo, Moessner, and Sondhi jointly formulated the influential theoretical account that identified the monopole excitations.",
        "maturity": "The theoretical framework is established and experimental signatures have been reported, though the excitations are emergent and their interpretation relies on a body of evidence.",
        "uncertainties": [
          "How directly experimental measurements establish monopoles as quasiparticles, rather than an effective description, remains a point for careful assessment."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B026",
      "proposed_laureates": [
        "Charles L. Kane",
        "Laurens W. Molenkamp",
        "Qi-Kun Xue"
      ],
      "assessment": {
        "nobel_worthiness": "Topological insulators and quantum spin Hall physics established a new organizing principle for electronic phases and led to broad experimental and theoretical advances.",
        "attribution": "Kane provided foundational theory; Molenkamp demonstrated the quantum spin Hall state in HgTe; Xue's work contributed to experimental quantum anomalous Hall physics.",
        "maturity": "Topological insulating behavior is robustly established, although the ballot combines related effects with distinct histories.",
        "uncertainties": [
          "The proposed attribution spans multiple discoveries, and overlap with other candidate framings makes the prize scope unclear."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B003",
      "proposed_laureates": [
        "Henry J. Snaith",
        "Nam-Gyu Park",
        "Tsutomu Miyasaka"
      ],
      "assessment": {
        "nobel_worthiness": "Metal-halide perovskite solar cells produced a rapid and scientifically important advance in photovoltaic performance and created a major materials research field.",
        "attribution": "Miyasaka reported early perovskite sensitized cells; Park and Snaith independently established efficient solid-state devices and drove decisive improvements.",
        "maturity": "The laboratory performance is compelling and extensively replicated, but stability and long-term deployment remain active issues.",
        "uncertainties": [
          "The relative weight of the initial demonstration and subsequent performance breakthroughs is debatable."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B022",
      "proposed_laureates": [
        "Antoine Georges",
        "Dieter Vollhardt",
        "Gabriel Kotliar"
      ],
      "assessment": {
        "nobel_worthiness": "Dynamical mean-field theory transformed the quantitative study of strongly correlated electrons and became a widely used framework for real materials.",
        "attribution": "Georges, Vollhardt, and Kotliar were central to developing and establishing the method and its applications.",
        "maturity": "The framework has been tested and extended over decades and is a mature part of condensed-matter theory.",
        "uncertainties": [
          "A theory-method prize would need to distinguish the core conceptual advance from the larger community's later development and use."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B002",
      "proposed_laureates": [
        "Christophe Salomon",
        "Rudolf Grimm",
        "Wolfgang Ketterle"
      ],
      "assessment": {
        "nobel_worthiness": "Strongly interacting Fermi gases provide a remarkably controllable setting for studying universal quantum matter and connections to superconductivity.",
        "attribution": "Salomon, Grimm, and Ketterle were leading experimental pioneers who created and characterized important strongly interacting regimes.",
        "maturity": "The experimental platform and its central results are robust, but the Nobel-scale discovery is less sharply bounded than for some other candidates.",
        "uncertainties": [
          "The field has many major contributors, and the credit assigned to this particular group may omit important parallel work."
        ]
      }
    }
  ]
